function sourceHref(ref) {
  const found = sourceFiles.find(([prefix]) => ref.startsWith(prefix));
  if (found) return encodeURI(`evidence/${found[1]}`);
  if (ref === 'Final schedules' || ref === 'Management Bridge') return 'final-schedules.xlsx';
  return null;
}
function sourceDescription(ref) {
  const exact = sourceInfo[ref];
  if (exact) return exact;
  const found = Object.keys(sourceInfo).find(key => ref.startsWith(key));
  return found ? sourceInfo[found] : `${ref} · evidence reference recorded in the decision register.`;
}
function table(title, rows, totalRows = []) {
  const row = ([name, value, cls = '']) => `<tr class="${cls}"><td>${name}</td><td class="${value < 0 ? 'negative' : ''}">${signed(value)}</td></tr>`;
  return `<article class="card"><div class="card-header"><h2>${title}</h2><p>EUR · period ended 31 August 2026</p></div><div class="table-wrap"><table><tbody>${rows.map(row).join('')}${totalRows.map(row).join('')}</tbody></table></div></article>`;
}
function flatRows(obj, names = {}) { return Object.entries(obj).map(([key, value]) => [names[key] || label(key), value]); }
function evidenceTags(items) { return items.map(item => `<button type="button" class="evidence-tag" data-evidence="${item.replace(/"/g, '&quot;')}">${item}</button>`).join(''); }
function effectRows(effect) { return Object.entries(effect).filter(([,v]) => v !== null).map(([k,v]) => `<tr><td>${label(k)}</td><td class="${v < 0 ? 'negative' : 'positive'}">${v > 0 ? '+' : ''}${signed(v)}</td></tr>`).join('') || '<tr><td colspan="2">No direct statement effect recorded.</td></tr>'; }
function effectDetail(d) {
  if (!d.effectNarrative) return '';
  const alternative = d.alternativeEffect ? `<h3>${d.alternativeEffect.label}</h3><div class="table-wrap"><table class="effect-table"><tbody>${effectRows({profit:d.alternativeEffect.profit,cash:d.alternativeEffect.cash,assets:d.alternativeEffect.assets,liabilities:d.alternativeEffect.liabilities,equity:d.alternativeEffect.equity})}<tr><td>Resulting profit</td><td class="positive">${number(d.alternativeEffect.resultingProfit)}</td></tr><tr><td>Resulting assets</td><td class="positive">${number(d.alternativeEffect.resultingAssets)}</td></tr><tr><td>Resulting equity</td><td class="positive">${number(d.alternativeEffect.resultingEquity)}</td></tr></tbody></table></div>` : '';
  return `<div class="effect-detail"><h3>Effect basis</h3><p>${d.effectNarrative}</p>${alternative}</div>`;
}
function decisionCard(d) {
  const isMaterial = d.reviewTier === 'material_judgment';
  const trail = isMaterial ? `<div class="trail"><div><h3>First-agent proposal</h3><p>${d.aiProposal}</p></div><div><h3>Independent challenge</h3><p>${d.independentChallenge}</p></div><div class="student"><h3>Student conclusion & reasoning</h3><p>${d.studentReasoning}</p></div></div><h3>Statement effect — original transaction / selected position</h3><div class="table-wrap"><table class="effect-table"><tbody>${effectRows(d.statementEffect)}</tbody></table></div>${effectDetail(d)}` : '';
  return `<details class="decision"><summary><span class="decision-id">${d.id}</span><span class="decision-question">${d.question}</span><span class="confidence ${d.confidence}">${d.confidence}</span></summary><div class="decision-body"><h3>Conclusion</h3><p>${d.answer}</p><h3>Evidence reviewed</h3><div class="evidence-tags">${evidenceTags(d.evidence)}</div>${trail}</div></details>`;
}
function scheduleCard(title, intro, rows, total) {
  return `<article class="schedule-card"><h2>${title}</h2><p>${intro}</p>${rows.map(([l,v]) => `<div class="schedule-row"><span>${l}</span><span class="${v < 0 ? 'negative' : ''}">${signed(v)}</span></div>`).join('')}<div class="schedule-row"><span>${total[0]}</span><span>${signed(total[1])}</span></div></article>`;
}
